/** Controlled migration of executable script CSP away from unsafe-inline.
 * The nonce is newly generated by Proxy for each HTML navigation; it is
 * never a session secret or authentication token.
 *
 * Do not enable before interactive browser acceptance. Next.js nonce handling
 * makes HTML routes dynamic and must be verified with streaming, payment and
 * redirect invariants (especially historical /not-found 307/308 behavior).
 */
export function buildNoncedScriptCsp(
  nonce: string,
  imageSources: readonly string[],
  options: { dev?: boolean; upgradeInsecure?: boolean } = {},
): string {
  if (!/^[A-Za-z0-9+/]{16,128}={0,2}$/.test(nonce)) {
    throw new TypeError("CSP nonce must be newly generated standard base64");
  }
  // Preserve existing Razorpay connectivity; do not add strict-dynamic
  // before provider-controlled script loading is understood and exercised.
  return [
    "default-src 'self'",
    "script-src 'self' 'nonce-" + nonce + "'" +
      (options.dev ? " 'unsafe-eval'" : "") + " https://checkout.razorpay.com",
    "script-src-attr 'none'",
    "style-src 'self' 'unsafe-inline'",
    "img-src " + imageSources.join(" "),
    "font-src 'self' data:",
    "connect-src 'self' https://api.razorpay.com",
    "frame-src https://api.razorpay.com https://checkout.razorpay.com",
    "object-src 'none'",
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    ...(options.upgradeInsecure ? ["upgrade-insecure-requests"] : []),
  ].join("; ");
}

/** Accepted origins must be HTTPS; ignore embedded credentials. */
export function allowedNonceCspImageSources(urls: readonly (string | undefined)[]) {
  const result = new Set<string>(["'self'", "blob:", "data:"]);
  for (const value of urls) {
    if (!value?.trim()) continue;
    try {
      const url = new URL(value.trim());
      if (url.protocol === "https:" && !url.username && !url.password) result.add(url.origin);
    } catch { /* Fail closed on invalid environment values. */ }
  }
  return [...result];
}

export function nonceCspEnabled(flag: string | undefined) {
  return flag === "true";
}
